import {openDialog,closeDialog} from './ui.js?v=0.6.0';
import {illustration} from './illustrations.js?v=0.6.0';
import {playAnnouncement,stopForeground} from './audio.js?v=0.6.0';
let queue=[],running=false,skipCurrent=null;
export function announceAll(items){queue.push(...items);queueMicrotask(drain);}
export function clearAnnouncements(){queue=[];skipCurrent?.();stopForeground();}
async function drain(){if(running||!queue.length)return;running=true;const item=queue.shift(),root=document.createElement('dialog');root.className='announcement '+(item.major?'major':'');root.setAttribute('aria-label','人生喜报');const card=document.createElement('div');card.className='announcement-card';const badge=document.createElement('span');badge.className='eyebrow';badge.textContent=({grade:'学年喜报',school:'金榜新章',graduation:'学有所成',promotion:'任职喜报',marriage:'良缘天成',birth:'新生命的到来',retirement:'功成归田',divorce:'各自前行','descendant-marriage':'家族添喜'})[item.type]||'人生新章';const h=document.createElement('h2');h.textContent=item.text;const skip=document.createElement('button');skip.textContent='跳过播报';skip.className='smallbtn';const art=document.createElement("div");art.innerHTML=illustration(item);card.append(badge,art,h);if(item.review?.lines?.length){const recap=document.createElement('section');recap.className='annual-recap';const title=document.createElement('h3');title.textContent=item.review.age+'岁 · 过去一年大事记';const list=document.createElement('ul');for(const text of item.review.lines){const li=document.createElement('li');li.textContent=text;list.append(li);}recap.append(title,list);card.append(recap);skip.textContent='读完了 · 继续播报';}card.append(skip);root.append(card);if(item.major){const bolt=document.createElement('div');bolt.className='lightning';bolt.setAttribute('aria-hidden','true');root.append(bolt);}document.body.append(root);openDialog(root);const duration=Math.min(16000,Math.max(3000,item.text.length*180));let timer;const dismiss=new Promise(resolve=>{const finish=()=>{clearTimeout(timer);resolve();};if(!item.review)timer=setTimeout(finish,duration);skipCurrent=()=>{stopForeground();finish();};skip.onclick=skipCurrent;root.addEventListener("cancel",e=>{e.preventDefault();skipCurrent?.();});});const played=playAnnouncement(item).catch(()=>({unavailable:true}));if(item.review)await dismiss;else await Promise.race([played.then(()=>new Promise(r=>setTimeout(r,1100))),dismiss]);clearTimeout(timer);closeDialog(root);root.remove();skipCurrent=null;running=false;drain();}





